        vbrp_bill.J_3GPMAUFV as VBRP_BILL_PM_ORDER_NUMBER_J_3GPMAUFV,
        vbrp_bill.J_3GETYPA as VBRP_BILL_SENDING_RECIPIENT_TYPE,
        vbrp_bill.J_3GETYPE as VBRP_BILL_RECEIVING_RECIPIENT_TYPE,
        vbrp_bill.J_3GORGUEB as VBRP_BILL_INDICATOR_ACROSS_ALL_ORGANIZATIONAL_STRUCTURES,
        vbrp_bill.PRS_WORK_PERIOD as VBRP_BILL_WORK_PERIOD,
        vbrp_bill.PPRCTR as VBRP_BILL_PARTNER_PROFIT_CENTER,
        vbrp_bill.PARGB as VBRP_BILL_TRADING_PARTNER_S_BUSINESS_AREA,
        vbrp_bill.AUFPLOAA as VBRP_BILL_ROUTING_NUMBER_OF_OPERATIONS_IN_THE_ORDER_AUFPLOAA,
        vbrp_bill.APLZLOAA as VBRP_BILL_INTERNAL_COUNTER_APLZLOAA,
        vbrp_bill.CAMPAIGN as VBRP_BILL_GENERIC_PROJECT_PLANNING_GUID_FROM_EXTERNAL_R_3_SYSTEM,
        vbrp_bill.COMPREAS as VBRP_BILL_ABBREVIATION_FOR_COMPLAINTS_REASON,
        vbrp_bill.WRF_CHARSTC1 as VBRP_BILL_CHARACTERISTIC_VALUE_1,
        vbrp_bill.WRF_CHARSTC2 as VBRP_BILL_CHARACTERISTIC_VALUE_2,
        vbrp_bill.WRF_CHARSTC3 as CHARACTERISTIC_VALUE_3
    FROM vbak_cte vbak --Sales Head
        LEFT JOIN vbap_cte vbap --Sales Line
            ON try_to_number(vbap.VBELN) = try_to_number(vbak.VBELN)
        LEFT JOIN lips_cte lips -- Delivery Line
            ON try_to_number(lips.VGBEL) = try_to_number(vbap.VBELN) AND try_to_number(lips.VGPOS) = try_to_number(vbap.POSNR)
        LEFT JOIN likp_cte likp -- Delivery Head
            ON try_to_number(likp.VBELN) = try_to_number(lips.VBELN)
        LEFT JOIN {{ ref('BRONZE__TEH_SALES_TO_INSTALLATION__SAPAPI_ZCDV_T_CMTU015_VBRP') }}  vbrp_bill -- Billing Document Item
            ON try_to_number(vbrp_bill.VGBEL)= try_to_number(lips.VBELN) AND try_to_number(vbrp_bill.VGPOS) = try_to_number(lips.POSNR)
        LEFT JOIN {{ ref('BRONZE__TEH_SALES_TO_INSTALLATION__SAPAPI_ZCDV_T_CMTU014_VBRK') }} vbrk_bill -- Billing Document Head
            ON try_to_number(vbrk_bill.VBELN) = try_to_number(vbrp_bill.VBELN)
),

